alter table public.instructors alter column user_id drop not null;
alter table public.instructors add column photo_url text, add column photo_path text, add column photo_width integer not null default 1200 check(photo_width>0), add column photo_height integer not null default 1600 check(photo_height>0), add column photo_crop integer[], add column sort_order integer not null default 0;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('instructor-photos','instructor-photos',true,4194304,array['image/jpeg','image/png','image/webp']);
create policy instructor_photos_read on storage.objects for select to anon,authenticated using(bucket_id='instructor-photos');
create policy instructor_photos_create on storage.objects for insert to authenticated with check(bucket_id='instructor-photos' and private.is_staff());
create policy instructor_photos_update on storage.objects for update to authenticated using(bucket_id='instructor-photos' and private.is_staff()) with check(bucket_id='instructor-photos' and private.is_staff());
create policy instructor_photos_delete on storage.objects for delete to authenticated using(bucket_id='instructor-photos' and private.is_staff());
insert into public.instructors(public_name,bio,photo_url,photo_width,photo_height,photo_crop,sort_order) values('Jennifer Solano','Born in Costa Rica, Jennifer Solano began dancing at age five and went on to become a certified ballroom instructor. Her career has taken her from Hawaii, Los Angeles and New York to eight years in Las Vegas. Her experience includes studio instruction, television dance work and live concert performances, bringing polished professional experience and a lifelong passion for dance to her students.','/instructors/jennifer-solano-dance.jpg',1536,1532,null,0);
insert into public.instructors(public_name,bio,photo_url,photo_width,photo_height,photo_crop,sort_order) values('Rody Broussard','Rody Broussard brings 40 years of dancing and teaching experience to the floor. He teaches Ballroom, Country and Cajun styles, working with students from beginner through advanced levels. His instruction spans social and competitive dancing as well as private and group lessons, with an emphasis on patient teaching, strong technique and helping every student become comfortable and confident on the dance floor.','/instructors/rody-broussard.jpg',1153,1536,null,1);
insert into public.instructors(public_name,bio,photo_url,photo_width,photo_height,photo_crop,sort_order) values('Mandy Frazier','Mandy Frazier brings 19 years of dance experience as an instructor, choreographer and dance educator. Her background includes extensive performance, competitive dance and classroom instruction, from school dance programs to college-level courses. Mandy combines technique, energy and encouragement to help students strengthen their skills, build confidence and develop a lasting enjoyment of dance.','/instructors/mandy-frazier.jpg',1135,1536,array[27,218,1055,1318],2);
insert into public.instructors(public_name,bio,photo_url,photo_width,photo_height,photo_crop,sort_order) values('Dale Tosczak','Dale Tosczak has taught dance since 2000, beginning in Country before expanding into American Style Ballroom, Latin, Salsa and Tango. A two-time UCWDC World Championships Pro-Pro Division winner, Dale is proficient in more than 20 dances. He teaches beginner through advanced students in both social and competitive formats, including Pro-Am, while keeping lessons approachable, engaging and enjoyable.','/instructors/dale-tosczak.jpg',1181,1536,null,3);
insert into public.instructors(public_name,bio,photo_url,photo_width,photo_height,photo_crop,sort_order) values('Sue McCann','Sue McCann began competing in 2000 and is a three-time world champion in Country Western dance. A certified American Country Western Dance judge, she has taught since 2006 and works with both social and competitive dancers. Sue focuses on clear instruction, confidence and enjoyment, helping students take their first steps or continue developing toward their next goal on the dance floor.','/instructors/sue-mccann.png',1152,1536,null,4);
